from pathlib import Path
from collections import defaultdict
p=Path('\\''bench/2026-09-23_playmode'\\'')
man=json.loads((p/'\\''runs_manifest.json'\\'').read_text())
groups=defaultdict(list);events=defaultdict(list);states=defaultdict(list)
for group in ['\\''main'\\'','\\''supplemental'\\'']:
 for key in man['\\''groups'\\''][group]:
  d=json.loads((p/'\\''summary'\\''/(key+'\\''.json'\\'')).read_text(encoding='\\''utf-8-sig'\\''))
  scenario=d['\\''scenario'\\'']
  groups[(scenario,d['\\''snapshot_slot'\\''],d['\\''camera_position'\\''],d['\\''camera_orthographic_size'\\''])].append(key)
  if scenario.startswith('\\''E'\\''):
   with (p/'\\''csv_from_raw'\\''/(key+'\\''.csv'\\'')).open(encoding='\\''utf-8-sig'\\'') as f:rows=list(csv.DictReader(f))
   marker='\\''tnd_bench_t1_conquerui_calls'\\'' if scenario=='\\''EDepart'\\'' else '\\''tnd_bench_t1_modeenter_calls'\\''
   frames=tuple(int(r['\\''frame_index'\\'']) for r in rows if int(r[marker])>0)
   events[(scenario,frames)].append(key)
   states[(scenario,d['\\''warmup_frames'\\''],d['\\''warmup_toggles_mode'\\''],json.dumps(d['\\''territory_before'\\'']),json.dumps(d['\\''territory_after'\\'']))].append(key)
for k,v in groups.items():print('\\''환경'\\'',k,len(v))
for k,v in events.items():print('\\''발화'\\'',k,len(v))
for k,v in states.items():print('\\''준비'\\'',k,len(v))
for group in ['\\''main'\\'','\\''supplemental'\\'','\\''all'\\'']:
 r=subprocess.run([sys.executable,'\\''bench/summarize.py'\\'',str(p),'\\''--group'\\'',group],capture_output=True)
 print('\\''출력'\\'',group,'\\''종료'\\'',r.returncode,'\\''바이트 일치'\\'',r.stdout==(p/'\\''summary'\\''/f'\\''summarize_output_{group}.md'\\'').read_bytes())
for name in ['\\''summarize.py'\\'','\\''test_summarize.py'\\'']:print('\\''보관 소스 일치'\\'',name,Path('\\''bench'\\'',name).read_bytes()==(p/'\\''source'\\''/name).read_bytes())
'"

